def send(device, m):
    prev = dedupe.get(device.id + '#' + m.client_msg_id)
    if prev: return SentAck(m.client_msg_id, prev.msg_id, prev.seq)
    seq = sequencer.next_seq(m.conv_id)            # owner shard, in-memory counter
    msg_id = snowflake()
    store.insert(conv=m.conv_id, bucket=bucket(now()), seq=seq, ...)   # LOCAL_QUORUM
    for dev in recipients_devices(m.conv_id):
        inbox.append(dev, msg_id, m.conv_id)
    dedupe.put(device.id + '#' + m.client_msg_id, (msg_id, seq), ttl=7*DAY)
    route_async(msg_id, recipients_devices(m.conv_id))
    return SentAck(m.client_msg_id, msg_id, seq)

def route_async(msg_id, devices):
    sessions = registry.lookup(devices)              # one MGET
    by_gw = group_by(sessions.online, key='gateway_id')
    for gw, devs in by_gw.items():
        rpc(gw).deliver(msg_id, devs, timeout=200ms)  # gateway writes to sockets
    for dev in sessions.offline:
        push.notify(dev, collapse_key=conv_of(msg_id))
    schedule(check_acks, msg_id, after=10s)          # redeliver or push if unacked

def reconnect_loop():
    attempt = 0
    while not connected():
        delay = random.uniform(0, min(60_000, 500 * 2 ** attempt))   # ms
        sleep(delay)
        if try_connect(): sync(from_cursor=local_db.inbox_cursor); outbox.flush()
        attempt += 1
